import hashlib,json,statistics,subprocess,sys
from pathlib import Path
root=Path(__file__).resolve().parents[1];sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
meta=json.loads((root/'artifacts/accept-fairness-candidate.json').read_text());driver=json.loads((root/'artifacts/accept-fairness-driver.json').read_text())
servers={'before':root/meta['baseline']['path'],'selected':root/meta['directory']/'war-relay'}
client=root/meta['helper']['directory']/'admission';runner=root/driver['directory']/'scripts/admission-flood.py'
output=root/'docs/benchmarks/2026-10-16-accept-fairness-comparison.json'
cohorts=[(1,'global',0),(4,'global',0),(1,'global',64),(1,'global',256),(1,'ip',256),(4,'global',256),(4,'ip',256)]
record={'scope':'Forty-two sequential fresh-process cases, three alternating six-second rounds. Accept quantum64 before,16 selected; configured1024 backlog unchanged on every listener. One/four workers and0/64/256 policy-refused clients under global or direct-IP capacity1. Fresh network namespace and independent generators per case: server CPUs0-3, echoCPU4,floodCPUs5-7. Verify exact full bodies/sender/FIFO, negotiated CBOR, Close/EOF, refused TCP EOF/reset with no bytes, counts/bytes and resource retirement. Healthy throughput uses its own actual phase; total CPU/elapsed includes final refusal tails. No builds, profiles, injected faults or competing loads overlap timings. Every failure is retained without replacement.', 'candidate':meta,'driver':driver,'driver_source':Path(__file__).read_text(),'variants':{k:{'path':str(p.relative_to(root)),'sha256':sha(p)} for k,p in servers.items()},'client':{'path':str(client.relative_to(root)),'sha256':sha(client)},'cases':[],'passed':False}
for repetition in range(1,4):
 for workers,policy,flood in cohorts if repetition%2 else reversed(cohorts):
  for role in ['before','selected'] if repetition%2 else ['selected','before']:
   cohort=f'w{workers}-{policy}-n{flood}'
   trace=output.with_name(f'2026-10-16-accept-fairness-{cohort}-{role}-{repetition}.json')
   command=[sys.executable,str(runner),'--server',str(servers[role]),'--client',str(client),'--workers',str(workers),'--policy',policy,'--flood-workers',str(flood),'--seconds','6','--isolate','--output',str(trace)]
   done=subprocess.run(command,cwd=root,capture_output=True,text=True,timeout=100)
   data=json.loads(trace.read_text());row={'cohort':cohort,'workers':workers,'policy':policy,'flood_workers':flood,'kind':role,'repetition':repetition,'passed':data['passed'],'exit_code':done.returncode,'trace':str(trace.relative_to(root)),'sha256':sha(trace),'error':data.get('error'),'tcp_counter_delta':data.get('tcp_counter_delta')}
   if data['passed']:
    assert done.returncode==0 and not data['profile_diagnostic'] and data['isolated_namespace']
    assert data['server_sha256']==record['variants'][role]['sha256'] and data['client_sha256']==record['client']['sha256']
    assert data['server_exit_code']==data['client_exit_code']==0
    assert all(q['backlog']==1024 for q in data['listener_queues_before'])
    m=data['mixed'];row.update(healthy=m['healthy']['per_second'],healthy_p99_ms=m['healthy']['p99_upper_ms'],healthy_max_ms=m['healthy']['max_ms'],refused=m['refusals']['per_second'],refused_p99_ms=m['refusals']['p99_upper_ms'],refused_max_ms=m['refusals']['max_ms'],cpu_wall=m['server_cpu_per_wall'],cpu_user=m['server_cpu_times']['user'],cpu_system=m['server_cpu_times']['system'],phase_seconds=m['elapsed_seconds'],healthy_seconds=m['healthy_elapsed_seconds'],rss_mib=data['events'][1]['process']['VmRSS']/1024)
   record['cases'].append(row);output.write_text(json.dumps(record,indent=2)+'\n');print(json.dumps(row),flush=True)
record['medians']={}
for workers,policy,flood in cohorts:
 cohort=f'w{workers}-{policy}-n{flood}'
 for role in servers:
  rows=[r for r in record['cases'] if r['cohort']==cohort and r['kind']==role];good=[r for r in rows if r['passed']]
  summary={'passed_runs':len(good),'failed_runs':len(rows)-len(good)}
  if good:
   fields=['healthy','healthy_p99_ms','healthy_max_ms','refused','refused_p99_ms','refused_max_ms','cpu_wall','cpu_user','cpu_system','phase_seconds','healthy_seconds','rss_mib']
   summary.update({n:statistics.median(r[n] for r in good) for n in fields});summary['ranges']={n:[min(r[n] for r in good),max(r[n] for r in good)] for n in fields}
  record['medians'][cohort+'/'+role]=summary
record['passed']=len(record['cases'])==42 and all(r['passed'] for r in record['cases'])
output.write_text(json.dumps(record,indent=2)+'\n');print(json.dumps({'passed':record['passed'],'cases':len(record['cases'])}),flush=True)
assert record['passed']
subprocess.run([sys.executable,str(root/'artifacts/accept-fairness-routing-guard.py')],cwd=root,check=True)
